class CareOffersScreen extends StatefulWidget{final String requestId;const CareOffersScreen({super.key,required this.requestId});@override State<CareOffersScreen> createState()=>_CareOffersScreenState();}
class _CareOffersScreenState extends State<CareOffersScreen>{bool _loading=true,_accepting=false;CareRequest? _request;List<QueryDocumentSnapshot<Map<String,dynamic>>> _offers=[];final Map<String,String> _nursePhotos={};String t(String k)=>AppStrings.t(k);bool get en=>LocaleController.instance.isEnglish;String tx(String ar,String english)=>en?english:ar;
 @override void initState(){super.initState();_load();}
 Future<void> _loadNursePhotos(List<QueryDocumentSnapshot<Map<String,dynamic>>> offers)async{_nursePhotos.clear();final ids=offers.map((o)=>o.data()['nurseId']?.toString()??'').where((id)=>id.isNotEmpty).toSet();await Future.wait(ids.map((id)async{try{final s=await FirebaseFirestore.instance.collection('nurseProfiles').doc(id).get();final p=s.data()?['photoUrl']?.toString().trim()??'';if(p.isNotEmpty)_nursePhotos[id]=p;}catch(_){}}));}
 Future<void> _load()async{if(mounted)setState(()=>_loading=true);try{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)throw Exception('auth');final db=FirebaseFirestore.instance;final requestSnap=await db.collection('careRequests').doc(widget.requestId).get();if(!requestSnap.exists||requestSnap.data()?['clientId']!=uid)throw Exception('not allowed');final snap=await db.collection('careOffers').where('requestId',isEqualTo:widget.requestId).limit(50).get();final offers=snap.docs.where((d){final s=d.data()['status']?.toString()??'';return s=='pending'||s=='accepted';}).toList()..sort((a,b){final aa=a.data()['status']=='accepted',ba=b.data()['status']=='accepted';if(aa!=ba)return aa?-1:1;final ap=(a.data()['proposedPrice'] as num?)?.toDouble()??double.infinity,bp=(b.data()['proposedPrice'] as num?)?.toDouble()??double.infinity;return ap.compareTo(bp);});await _loadNursePhotos(offers);if(mounted)setState((){_request=CareRequest.fromFirestore(requestSnap);_offers=offers;_loading=false;});}catch(_){if(mounted)setState((){_request=null;_offers=[];_loading=false;});}}
 Future<void> _accept(QueryDocumentSnapshot<Map<String,dynamic>> offer)async{if(_accepting)return;final uid=FirebaseAuth.instance.currentUser?.uid;final request=_request;if(uid==null||request==null)return;setState(()=>_accepting=true);try{final db=FirebaseFirestore.instance;final requestRef=db.collection('careRequests').doc(request.id);final offerRef=db.collection('careOffers').doc(offer.id);final bookingRef=db.collection('bookings').doc();final pending=await db.collection('careOffers').where('requestId',isEqualTo:request.id).where('status',isEqualTo:'pending').limit(50).get();await db.runTransaction((transaction)async{final req=await transaction.get(requestRef);final selected=await transaction.get(offerRef);if(!req.exists||req.data()?['clientId']!=uid||req.data()?['status']!='open')throw Exception('closed');if(!selected.exists||selected.data()?['status']!='pending')throw Exception('offer');final d=selected.data()!;final nurseId=d['nurseId']?.toString()??'';final selectedPrice=(d['proposedPrice'] as num?)?.toDouble()??0;final hours=(req.data()?['shiftHours'] as num?)?.toInt()??0;final days=(req.data()?['daysCount'] as num?)?.toInt()??1;final raw=req.data()?['startDate'];final start=raw is Timestamp?raw.toDate():DateTime.now();final parts=(req.data()?['startTime']?.toString()??'08:00').split(':');final hour=(int.tryParse(parts.first)??8).clamp(0,23).toInt();final minute=(int.tryParse(parts.length>1?parts[1]:'0')??0).clamp(0,59).toInt();if(nurseId.isEmpty||selectedPrice<=0||!CareRequest.allowedShiftHours.contains(hours))throw Exception('invalid');final shiftStart=DateTime(start.year,start.month,start.day,hour,minute);final base=selectedPrice*days;final fee=base*.10;transaction.update(requestRef,{'status':'booked','selectedNurseId':nurseId,'selectedOfferId':offer.id,'updatedAt':FieldValue.serverTimestamp()});transaction.update(offerRef,{'status':'accepted','updatedAt':FieldValue.serverTimestamp()});transaction.set(bookingRef,{'clientId':uid,'nurseId':nurseId,'careRequestId':request.id,'offerId':offer.id,'shiftStart':Timestamp.fromDate(shiftStart),'shiftEnd':Timestamp.fromDate(shiftStart.add(Duration(hours:hours))),'shiftHours':hours,'pricePerHour':selectedPrice/hours,'pricePerShift':selectedPrice,'daysCount':days,'platformFee':fee,'totalAmount':base+fee,'status':'pending_payment','paymentStatus':'unpaid','createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});});final batch=db.batch();for(final other in pending.docs){if(other.id!=offer.id)batch.update(other.reference,{'status':'rejected','updatedAt':FieldValue.serverTimestamp()});}if(pending.docs.any((d)=>d.id!=offer.id))await batch.commit();if(mounted)context.go('/client/payment/${bookingRef.id}');}catch(_){if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(tx('العرض لم يعد متاحًا. حدّث الصفحة وحاول مرة أخرى.','This offer is no longer available. Refresh and try again.'))));await _load();}}finally{if(mounted)setState(()=>_accepting=false);}}
 @override Widget build(BuildContext context){if(_loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(_request==null)return Scaffold(appBar:AppBar(title:Text(tx('عروض الممرضين','Nurse offers'))),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.error_outline,size:56),const SizedBox(height:12),Text(tx('تعذر تحميل الطلب. تأكد من اتصالك بالإنترنت.','Unable to load the request. Check your internet connection.'),textAlign:TextAlign.center),const SizedBox(height:12),FilledButton(onPressed:_load,child:Text(t('retry')))])));final closed=_request!.status!='open';return Scaffold(appBar:AppBar(title:Text(tx('الممرضون والعروض','Nurses & offers')),actions:[IconButton(onPressed:_load,tooltip:t('retry'),icon:const Icon(Icons.refresh))]),body:RefreshIndicator(onRefresh:_load,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.fromLTRB(16,16,16,32),children:[Card(color:closed?AppColors.primaryLight:null,child:Padding(padding:const EdgeInsets.all(14),child:Row(children:[Icon(closed?Icons.check_circle_outline:Icons.people_alt_outlined,color:AppColors.primary),const SizedBox(width:10),Expanded(child:Text(closed?tx('تم اختيار الممرض لهذا الطلب.','A nurse has been selected for this request.'):tx('راجع العروض والتقييمات ثم اختر الممرض المناسب.','Review the offers and ratings, then choose the right nurse.')))]))),const SizedBox(height:10),if(_offers.isEmpty)Padding(padding:const EdgeInsets.only(top:90),child:Column(children:[const Icon(Icons.inbox_outlined,size:64),const SizedBox(height:12),Text(tx('لسه مفيش عروض على طلبك','No offers yet'),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(tx('عندما يقدم ممرض عرضًا سيظهر هنا.','Nurse offers will appear here when submitted.'),textAlign:TextAlign.center)]))else ..._offers.map((offer){final accepted=offer.data()['status']=='accepted';return Padding(padding:const EdgeInsets.only(bottom:10),child:_card(offer,disabled:closed,accepted:accepted));})]));}
 Widget _card(QueryDocumentSnapshot<Map<String,dynamic>> offer,{required bool disabled,required bool accepted}){final d=offer.data();final rating=(d['nurseRating'] as num?)?.toDouble()??0;final price=(d['proposedPrice'] as num?)?.toDouble()??0;final exp=d['nurseExperienceYears']??0;final nurseId=d['nurseId']?.toString()??'';final stored=d['nursePhotoUrl']?.toString().trim()??'';final photo=_nursePhotos[nurseId]??stored;return Card(margin:EdgeInsets.zero,child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(accepted)...[Container(width:double.infinity,padding:const EdgeInsets.symmetric(horizontal:12,vertical:8),decoration:BoxDecoration(color:AppColors.success.withValues(alpha:.10),borderRadius:BorderRadius.circular(10)),child:Text('✓ ${tx('الممرض المختار','Selected nurse')}',style:const TextStyle(color:AppColors.success,fontWeight:FontWeight.bold))),const SizedBox(height:12)],Row(crossAxisAlignment:CrossAxisAlignment.start,children:[GestureDetector(onTap:photo.isEmpty?null:()=>_showPhoto(photo),child:CircleAvatar(radius:30,backgroundColor:AppColors.primaryLight,backgroundImage:photo.isNotEmpty?NetworkImage(photo):null,child:photo.isEmpty?const Icon(Icons.person,size:30):null)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(d['nurseName']?.toString()??tx('ممرض','Nurse'),style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)),const SizedBox(height:4),Row(children:[if(d['nurseVerified']==true)const Icon(Icons.verified,size:16,color:AppColors.success),if(d['nurseVerified']==true)const SizedBox(width:4),Text(rating>0?'${rating.toStringAsFixed(1)} ⭐':tx('بدون تقييم','No rating')),const SizedBox(width:10),Text('$exp ${tx('سنوات خبرة','years experience')}')])])),Text('${price.toStringAsFixed(0)} ${t('currency_egp')}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18,color:AppColors.primary))]),const SizedBox(height:4),Text(tx('سعر الشيفت الواحد','Price per shift'),style:const TextStyle(color:AppColors.textSecondary,fontSize:12)),if((d['note']??'').toString().trim().isNotEmpty)Padding(padding:const EdgeInsets.only(top:12),child:Text(d['note'].toString())),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton(onPressed:nurseId.isEmpty?null:()=>context.push('/client/nurse-profile/$nurseId?requestId=${widget.requestId}'),child:Text(tx('عرض الملف والتقييمات','View profile & reviews')))),if(!accepted)...[const SizedBox(width:10),Expanded(child:FilledButton(onPressed:disabled||_accepting?null:()=>_accept(offer),child:Text(_accepting?tx('جاري الاختيار...','Selecting...'):tx('اختيار الممرض','Select nurse'))))]])])));}
 void _showPhoto(String url){showDialog<void>(context:context,builder:(_)=>Dialog(clipBehavior:Clip.antiAlias,child:InteractiveViewer(child:Image.network(url,fit:BoxFit.contain,errorBuilder:(_,__,___)=>Padding(padding:const EdgeInsets.all(40),child:Text(tx('تعذر تحميل الصورة','Unable to load image')))))));}
